})

pm.test("Each element contains the fields specified in the DTO", function () {
  const first = pm.response.json()[0];
  pm.expect(first).to.have.all.keys("code", "name", "shortDescription", "bannerUrl");
});

pm.test("Status 200", function () {
  pm.response.to.have.status(200);
});

pm.test("Specifically for Hanoi city, there is an 'images' section.", function () {
  const body = pm.response.json();
  pm.expect(body.code).to.eql("ha-noi");
  pm.expect(body.name).to.eql("Hà Nội");
  pm.expect(body.images).to.be.an("array");
});

pm.test("Status 404", function () {
  pm.response.to.have.status(404);
});

pm.test("Content-Type is application/problem+json", function () {
  pm.expect(pm.response.headers.get("Content-Type")).to.include("application/problem+json");
});

pm.test("Body in Problem Details (RFC 9457)", function () {
  const body = pm.response.json();
  pm.expect(body.type).to.eql("about:blank");
  pm.expect(body.title).to.eql("Not Found");
  pm.expect(body.status).to.eql(404);
  pm.expect(body).to.have.property("detail");
  pm.expect(body.instance).to.include("/destinations/not-found");
});
